<?php
namespace App\Policies;
use App\Models\{Payment,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class PaymentPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_payment');} public function view(User $u,Payment $r):bool{return $this->canForRecord($u,'view_payment',$r);} public function create(User $u):bool{return $u->can('create_payment');} public function update(User $u,Payment $r):bool{return $r->status==='pending'&&$this->canForRecord($u,'update_payment',$r);} public function delete(User $u,Payment $r):bool{return false;} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,Payment $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,Payment $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,Payment $r):bool{return false;} public function reorder(User $u):bool{return false;} public function complete(User $u,Payment $r):bool{return $this->canForRecord($u,'record_payment',$r);} public function void(User $u,Payment $r):bool{return $this->canForRecord($u,'void_payment',$r);} }
